param([string]$InputFile = "top-errors.json", [int]$Count = 10) $ErrorActionPreference = "Stop"; if (-not (Test-Path $InputFile)) { Write-Error "Input not found" }; $json = Get-Content $InputFile | ConvertFrom-Json; $top = $json | Select-Object -First $Count; foreach ($item in $top) { $clean = $item.file.Replace("..//..//", "").Replace("//", "/").Replace("\", "/"); if (Test-Path $clean) { Write-Host "Fixing $clean" -ForegroundColor Cyan; node scripts/agentic-corruption-fixer.mjs $clean } else { Write-Warning "Missing: $clean" } }
